INSERT INTO public.forum_posts (id, forum_thread_id, created_at, updated_at, created_by_id, content, sticky, locked) VALUES
    (1, 1, '2025-09-17 12:42:13.702455+00', '2025-09-17 12:42:13.702455+00', 1, 'Welcome!', false, DEFAULT) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.forum_posts (id, forum_thread_id, created_at, updated_at, created_by_id, content, sticky, locked) VALUES
    (3, 3, '2025-05-22 08:03:48.66391+00', '2025-05-22 08:03:48.66391+00', 1, 'Hello there, I just joined!', false, DEFAULT),
    (4, 5, '2025-05-22 08:06:36.225458+00', '2025-05-22 08:06:36.225458+00', 2, 'I use arch btw :)', false, DEFAULT),
    (10, 10, '2025-10-01 10:00:00+00', '2025-10-01 10:00:00+00', 2, 'I finally got fed up with my home connection choking on uploads, so I''m shopping for a seedbox. Anyone have opinions on providers that play nice with rtorrent + ruTorrent? I don''t need anything huge, just enough to keep a decent handful of torrents seeding around the clock.', false, DEFAULT),
    (11, 10, '2025-10-01 14:20:00+00', '2025-10-01 14:20:00+00', 5, 'I''ve been on Feral Hosting for about two years now and have zero complaints. Their semi-dedicated plans are cheap and the disk IO has never been a bottleneck for me, even with a few hundred torrents going at once.', false, DEFAULT),
    (12, 10, '2025-10-02 08:05:00+00', '2025-10-02 08:05:00+00', 4, 'I actually just run everything off an old desktop I turned into a NAS. Works fine except my upload gets capped hard during the day when the rest of the house is on video calls, so most of my seeding happens overnight.', false, DEFAULT),
    (13, 11, '2025-10-02 11:00:00+00', '2025-10-02 11:00:00+00', 4, 'Still getting the hang of how ratio works here. How much buffer should I try to build up before I start grabbing bigger releases? Don''t want to end up in the negative by accident.', false, DEFAULT),
    (14, 11, '2025-10-02 13:45:00+00', '2025-10-02 13:45:00+00', 1, 'A good rule of thumb is to keep a buffer of at least a few times the size of anything you plan to download next, so a bad week of uploads doesn''t put you underwater. Seeding smaller, popular torrents for a while is a low-risk way to build that up.', false, DEFAULT),
    (15, 11, '2025-10-03 09:12:00+00', '2025-10-03 09:12:00+00', 2, 'Seconding what''s been said, seeding a handful of well-seeded albums or discographies for a couple of weeks got my ratio comfortable enough that I stopped worrying about it entirely.', false, DEFAULT),
    (16, 12, '2025-10-03 15:00:00+00', '2025-10-03 15:00:00+00', 4, 'Currently seeding a whole documentary boxset I picked up last month, ratio on it is climbing nicely since it doesn''t seem to have many other seeders yet.', false, DEFAULT),
    (17, 12, '2025-10-03 19:22:00+00', '2025-10-03 19:22:00+00', 5, 'Got a big discography going that I''ve been keeping alive for months at this point, plus whatever new music drops I grab during the week.', false, DEFAULT),
    (18, 12, '2025-10-04 07:40:00+00', '2025-10-04 07:40:00+00', 2, 'Nothing exciting on my end, just a couple of TV seasons and one big game archive that refuses to die on my seedbox.', false, DEFAULT),
    (19, 13, '2025-10-04 10:30:00+00', '2025-10-04 10:30:00+00', 2, 'Trying to get cross-seeding working properly so the same files can count toward multiple torrents without wasting disk space. Anyone using autobrr or cross-seed successfully with this tracker?', false, DEFAULT),
    (20, 13, '2025-10-04 16:05:00+00', '2025-10-04 16:05:00+00', 5, 'Hardlinks are the way to go here, saved me a ton of space once I set it up right. Just make sure your download and seeding directories are on the same filesystem or the hardlinks silently turn into full copies.', false, DEFAULT),
    (21, 13, '2025-10-05 08:50:00+00', '2025-10-05 08:50:00+00', 1, 'Symlinks work too if you can''t hardlink across your setup, though some clients handle them a little differently when checking files on startup, so test carefully before relying on it.', false, DEFAULT),
    (22, 14, '2025-10-05 12:00:00+00', '2025-10-05 12:00:00+00', 5, 'Woke up to a dead drive last week that had years of carefully built up seeding history on it. No backup, obviously, so that ratio is just gone now. Learn from my mistake and back up your client''s session data.', false, DEFAULT),
    (23, 14, '2025-10-05 17:30:00+00', '2025-10-05 17:30:00+00', 4, 'Had a scare with SMART warnings piling up on one of my drives a while back. Managed to migrate everything off in time, but it was way too close for comfort.', false, DEFAULT),
    (24, 14, '2025-10-06 09:15:00+00', '2025-10-06 09:15:00+00', 2, 'This is why I''ve started keeping a small RAID array just for the seeding drives, at least that way one disk dying doesn''t take the whole library down with it.', false, DEFAULT);

